import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.CcKC9xfe.js";const g=JSON.parse('{"title":"Mailbox storage","description":"Mailbox backends (Maildir, sdbox, mdbox) and the FileIndex (binary mail-index v7.3 wire format: .index / .index.log / .index.names). All index mutations…","frontmatter":{"outline":[2,4],"head":[["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/storage/"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/latest/storage/"}],["meta",{"property":"og:title","content":"Mailbox storage"}],["meta",{"name":"twitter:title","content":"Mailbox storage"}],["meta",{"property":"og:description","content":"Mailbox backends (Maildir, sdbox, mdbox) and the FileIndex (binary mail-index v7.3 wire format: .index / .index.log / .index.names). All index mutations…"}],["meta",{"name":"twitter:description","content":"Mailbox backends (Maildir, sdbox, mdbox) and the FileIndex (binary mail-index v7.3 wire format: .index / .index.log / .index.names). All index mutations…"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/latest/storage/#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/latest/storage/\\",\\"headline\\":\\"Mailbox storage\\",\\"description\\":\\"Mailbox backends (Maildir, sdbox, mdbox) and the FileIndex (binary mail-index v7.3 wire format: .index / .index.log / .index.names). All index mutations…\\",\\"dateModified\\":\\"2026-10-23T14:59:16.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/latest/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Mailbox storage\\",\\"item\\":\\"https://doc.yarilomail.org/latest/storage/\\"}]}]}"]]},"headers":[],"relativePath":"storage/index.md","filePath":"storage/index.md","lastUpdated":1792767556000}'),d={name:"storage/index.md"};function r(i,e,n,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="mailbox-storage" tabindex="-1">Mailbox storage <a class="header-anchor" href="#mailbox-storage" aria-label="Permalink to &quot;Mailbox storage&quot;">​</a></h1><p>Mailbox backends (Maildir, sdbox, mdbox) and the FileIndex (binary mail-index v7.3 wire format: <code>.<wbr>index</code> / <code>.<wbr>index.<wbr>log</code> / <code>.<wbr>index.<wbr>names</code>). All index mutations go through the cross-process mailbox lock (<code>yarilo-locks</code>); sessions sharing a pod serialise on an in-process <code>sync.<wbr>RWMutex</code> — the Redis lock is only ever contested across pods, not within a single pod. See also <a href="/latest/storage/mdbox_alt.html">mdbox Alt Storage (Cold Tiering)</a>.</p><h2 id="path-templates" tabindex="-1">Path templates <a class="header-anchor" href="#path-templates" aria-label="Permalink to &quot;Path templates&quot;">​</a></h2><p>Every path setting that can differ per user — <code>mail_<wbr>home</code>, <code>mail_<wbr>path</code>, <code>mail_<wbr>inbox_<wbr>path</code>, <code>mail_<wbr>index_<wbr>path</code>, <code>mail_<wbr>control_<wbr>path</code>, <code>mail_<wbr>volatile_<wbr>path</code> and <code>mail_<wbr>alt_<wbr>path</code> — is a template expanded against the user. Two spellings are accepted, and nothing else is.</p><table tabindex="0"><thead><tr><th style="text-align:left;">short form</th><th style="text-align:left;">expression form</th><th style="text-align:left;">expands to</th></tr></thead><tbody><tr><td style="text-align:left;"><code>%u</code></td><td style="text-align:left;"><code>%{user}</code></td><td style="text-align:left;">the full username, <code>alice@example.<wbr>com</code></td></tr><tr><td style="text-align:left;"><code>%n</code></td><td style="text-align:left;"><code>%{user | username}</code></td><td style="text-align:left;">the local part, <code>alice</code></td></tr><tr><td style="text-align:left;"><code>%d</code></td><td style="text-align:left;"><code>%{user | domain}</code></td><td style="text-align:left;">the domain, <code>example.<wbr>com</code></td></tr><tr><td style="text-align:left;"><code>%h</code>, or a leading <code>~/</code></td><td style="text-align:left;"><code>%{home}</code></td><td style="text-align:left;">the user&#39;s home directory</td></tr><tr><td style="text-align:left;"><code>%2.<wbr>256Nu</code></td><td style="text-align:left;"><code>%{user | sha1 % 256 | hex(2)}</code></td><td style="text-align:left;">a hash bucket, <code>d5</code></td></tr><tr><td style="text-align:left;"><code>%%</code></td><td style="text-align:left;">—</td><td style="text-align:left;">a literal <code>%</code></td></tr></tbody></table><p>The expression form is a variable followed by filters: <code>username</code>, <code>domain</code>, <code>lower</code>, <code>upper</code>, <code>md5</code>, <code>sha1</code>, and <code>hex(n)</code>. A hash becomes a number through a modulo (<code>sha1 % 256</code>) and a number becomes text through <code>hex(n)</code>, which zero-pads to <code>n</code> digits and keeps the low ones; a negative width pads on the right and keeps the high ones.</p><p><strong>The two forms do not hash the same way, deliberately.</strong> An expression names its algorithm, so <code>%{user | sha1 % 256}</code> is SHA-1 while the older <code>%2.<wbr>256Nu</code> stays MD5. Each does what it says, and neither changes where an existing deployment&#39;s users already live. The expression form matches the reference implementation byte for byte, including reading the digest as a big-endian integer from its <strong>last</strong> eight bytes — so a config migrated from it keeps every user in the bucket they already had.</p><p><strong>A template that cannot be expanded stops startup</strong>, naming the key and the sequence that was not understood. There is no pass-through: a template copied from a newer reference config used to produce a directory literally named <code>%{user | sha1 % 256 | hex(2)}</code> — created, written to, and never mentioned.</p><p>The same templates are accepted in the matching userdb fields, and expanded the same way on every path — a delivery and an interactive session resolve one user to one set of directories. (Before 2.3.133 the delivery path resolved <code>~/</code> in <code>mail_<wbr>path</code> / <code>mail_<wbr>inbox_<wbr>path</code> but left <code>%u</code> alone, so the two could disagree.)</p><p>Hash buckets matter once a directory holds one entry per user, as a <code>mail_<wbr>volatile_<wbr>path</code> on a local disk does. The chart leaves the key unset; the example values use the short form:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mail_volatile_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/tmp/yarilo-volatile/%2.256Nu/%u&quot;</span></span></code></pre></div><p>Switching that to an expression changes the buckets — even <code>%{user | md5 % 256 | hex(2)}</code>, since the short form reads the first four bytes of the digest and the expression the last eight — so on a running deployment it moves every user&#39;s directory.</p><h2 id="maildir-sync-on-open" tabindex="-1">Maildir sync-on-open <a class="header-anchor" href="#maildir-sync-on-open" aria-label="Permalink to &quot;Maildir sync-on-open&quot;">​</a></h2><p><strong>Maildir sync-on-open</strong> (<code>storage.<wbr>maildir_<wbr>sync_<wbr>on_<wbr>select</code>, default <code>true</code>): on SELECT/EXAMINE, STATUS and IDLE the Maildir index is reconciled against <code>cur/</code> and <code>new/</code>, so a message delivered by an external MDA or moved/renamed by a second MUA appears without an operator rebuild — files in <code>new/</code> are migrated to <code>cur/</code>, new files gain a UID, vanished files are expunged, and out-of-band flag renames keep their UID. It is gated on a cheap <code>cur/</code>+<code>new/</code> mtime token, so a quiescent folder costs a single <code>stat</code>. Only Maildir honours it; dbox stays index-authoritative.</p><h2 id="dbox-reactive-rebuild" tabindex="-1">dbox reactive rebuild <a class="header-anchor" href="#dbox-reactive-rebuild" aria-label="Permalink to &quot;dbox reactive rebuild&quot;">​</a></h2><p><strong>dbox reactive rebuild</strong> (<code>storage.<wbr>dbox_<wbr>reactive_<wbr>rebuild</code>, default <code>true</code>): dbox is index-authoritative and does not scan storage on every access, but it self-heals reactively. When an <strong>sdbox</strong> read hits a missing or corrupt message file the folder is flagged (a persisted FSCKD marker in the index header); the next SELECT, STATUS or IDLE poll (or POP3 login) then heals the index under the mailbox lock — every record whose file has vanished is expunged (with a QRESYNC tombstone), surviving messages keep their UID. Transient I/O errors (EIO, timeouts) do not trigger a heal.</p><p>Turning the switch off stops the heal on every path, IMAP and the POP3 login alike. Reads still flag folders while it is off, so turning it back on heals them on the next open.</p><p><strong>mdbox</strong> now self-heals reactively too, the same way as sdbox: a read that trips over a missing/corrupt message flags the folder FSCKD, and the next SELECT/STATUS/IDLE poll (or POP3 login) runs a targeted per-folder heal under the mailbox lock — every index record whose message is no longer present in storage is expunged (QRESYNC tombstone), the rest keep their UID. This is per-folder and does <em>not</em> touch the shared map&#39;s refcounts, so it needs none of the quiescence the storage-wide rebuild does. Because it goes through the shared <code>box.<wbr>Scan</code>, a <strong>concurrent <code>purge</code>/<code>altmove</code></strong> (both write the new <code>m.<wbr>&lt;N&gt;</code> before unlinking the old) makes the scan incomplete and the heal <strong>abort-and-retry</strong> rather than mistake a just-compacted message for a vanished one — so if a folder stays FSCKD, check whether a purge is running. A structurally corrupt <code>m.<wbr>&lt;N&gt;</code> record also aborts the heal until an operator moves the bad file aside, and the vanished message&#39;s map refcount is not decremented by the heal (a leak the next operator rebuild + purge reclaims).</p><h2 id="mdbox-operator-rebuild" tabindex="-1">mdbox operator rebuild <a class="header-anchor" href="#mdbox-operator-rebuild" aria-label="Permalink to &quot;mdbox operator rebuild&quot;">​</a></h2><p>For the <strong>operator</strong> side, because mdbox messages are shared across folders through the map, a per-folder rebuild would import unrelated messages — so the per-folder endpoint (<code>/<wbr>api/<wbr>backend/<wbr>index/<wbr>rebuild</code>) returns <code>501</code> for mdbox and there is a dedicated <strong>storage-wide rebuild</strong>: <code>POST /<wbr>api/<wbr>backend/<wbr>index/<wbr>rebuild-storage {user}</code> (or <code>yarctl backend index rebuild-storage &lt;user&gt;</code>). It reconciles the shared map against the physical <code>m.<wbr>&lt;N&gt;</code> files under the storage lock, resets every folder index to the messages that still exist, <strong>recomputes each map record&#39;s refcount from the actual folder references</strong> (the reference <code>rebuild_<wbr>apply_<wbr>map</code> parity), drops map records whose message vanished, and bumps a persisted <code>rebuild_<wbr>count</code> generation counter in the map header. It <strong>refuses</strong> to run when the scan is incomplete (a half-corrupt <code>m.<wbr>&lt;N&gt;</code> or transient I/O — move/repair the named file and re-run) or when a configured alt tier is unmounted (would mass-expunge alt-resident mail). It is an operator repair tool (the reference <code>force-resync</code> parity) and should run with the user&#39;s mailboxes <strong>quiesced</strong> — no concurrent delivery <em>and</em> no concurrent folder operations (CREATE/DELETE/RENAME); neither the delivery folder-append nor the restore is serialised on the storage lock, so a concurrent message or folder change can race the rebuild.</p><p>Each map record is paired with the bytes it names: by its place in the file when the GUID there agrees, otherwise by its GUID wherever that message lies. A record found at another place is moved there and keeps its map_uid (reported as <code>repointed</code>); a record whose GUID is found nowhere is dropped as vanished. A folder record whose map_uid is gone, or names a message with a different GUID, takes the map_uid that holds its GUID (reported as <code>remapped</code>) instead of being dropped.</p><p>A message present on disk but referenced by no folder becomes <strong>zero-ref</strong> (reported as <code>unreferenced_<wbr>zeroref</code> and logged) so the next purge reclaims it — by default it is <strong>not</strong> re-filed into a mailbox.</p><p>Each mdbox message records the mailbox it was saved into (an <code>ORIG_<wbr>MAILBOX</code> key in the dbox trailer, appended after the GUID/size fields — an older reader ignores the unknown key). With <strong><code>restore_<wbr>orphans=true</code></strong> (<code>--restore-orphans</code> on the CLI) the rebuild re-files an unreferenced message that carries this tag back into its home folder (created if missing), via the normal append path so vsize/modseq/quota stay correct; untagged records are still left zero-ref. A restored orphan comes back with <strong>default flags</strong> (unseen, no keywords) — flags live in the fileindex and an orphan has no index record to recover them from (an accepted gap, like the VANISHED-tombstone gap of the reset path). Restore is off by default and per-request, because the tag proves only <em>&quot;was once in this folder&quot;</em>, not <em>&quot;is lost&quot;</em> — a delete-with-refcount-leak carries the same tag, so the resurrection decision stays the operator&#39;s. A default run (<code>restore_<wbr>orphans=false</code>) writes and reads the tag but takes no action, so its numbers are identical to a rebuild without the feature.</p><p>The rebuild <strong>preserves each surviving record&#39;s own modseq</strong> across the reset (no QRESYNC modseq storm on an operator rebuild); <code>highest_<wbr>modseq</code> advances to the greatest value carried in, and only a record with no modseq (a freshly assigned UID) is stamped fresh. It also <strong>notifies FTS to expunge</strong> every UID it drops, per folder — the storage-wide rebuild, the per-folder rebuild, and the reactive heal all return the dropped UIDs so their FTS documents are invalidated immediately instead of lingering as ghost entries until the next <code>fts rescan</code> (the POP3-only reactive heal has no FTS client wired in, so those still rely on the next rescan). One accepted gap remains: the reset still loses per-UID VANISHED tombstone fidelity for dropped records, since it rewrites the whole set.</p><h2 id="mdbox-on-disk-layout-rotation" tabindex="-1">mdbox on-disk layout &amp; rotation <a class="header-anchor" href="#mdbox-on-disk-layout-rotation" aria-label="Permalink to &quot;mdbox on-disk layout &amp; rotation&quot;">​</a></h2><p>On-disk <code>m.<wbr>&lt;N&gt;</code> files follow the <strong>dbox v2 layout</strong>: the ASCII file-header line (<code>version M&lt;hdr-size&gt; C&lt;create-stamp&gt;</code>) is written <strong>once per physical file</strong>, before its first message, then each message is <code>[header][body][trailer]</code>. The reader is self-describing — at each record it tells a file-header line (starts with the ASCII version digit) apart from a raw message header (starts with the <code>\\x01\\x02</code> magic) by the first byte, so a store written by another implementation parses past the first message in a multi-message file, and legacy yarilo stores that stamped the header before every record still read back unchanged (no migration).</p><h3 id="record-header-size" tabindex="-1">Record header size <a class="header-anchor" href="#record-header-size" aria-label="Permalink to &quot;Record header size&quot;">​</a></h3><p>The message header is <strong>30 bytes</strong>, announced as <code>M1e</code> in the file-header line: two magic bytes, the type byte <code>N</code>, spaces, the 16-character hex message size at offsets 13..29, and LF as the <strong>last</strong> byte. <code>u.<wbr>&lt;UID&gt;</code> files under sdbox carry the same header.</p><p><strong>The size is read from <code>M</code>, never assumed.</strong> Every reader — the fetch path, the compaction read, and both rebuild scanners — takes it from the file-header line that introduces the record, or from the file&#39;s own first line when the record is an appended one that carries none. That is what makes records written elsewhere readable: they announce their own size.</p><p>Builds before 2.4.1 wrote a 32-byte header and announced it as <code>M20</code>. Those stores are <strong>read unchanged</strong> — no migration, no rewrite — and nothing writes <code>M20</code> again.</p><p>A header is rejected when its last byte is not LF. That check is what catches a header read at the wrong size: read 32 bytes of a 30-byte header and the last byte is the first byte of the body, which is almost never a newline.</p><p><strong>What this does and does not buy.</strong> The <em>records</em> parse in both directions, and the claim rests on files another implementation actually wrote rather than on files built to match the description: a storage file carrying three records, only the first of them preceded by a file-header line, plus two single-message files, are held in the server tree and read by the tests on every run. In the other direction the record this server writes is held against one of those — the file-header line and the message header byte for byte, since those are the parts the other implementation reads before it appends, and the metadata trailer by its keys and values, since the two implementations write those lines in different orders.</p><p><strong>Serving</strong> such a record is covered too. Another implementation can store a body with bare LF; since 2.4.1 the body is converted to CRLF on the way out, and mdbox reports the size it will actually serve, as sdbox already did, so <code>RFC822.<wbr>SIZE</code> and the bytes a client receives agree. Mail this server wrote is CRLF on disk already and comes back byte for byte.</p><p>The <em>store</em> is a different question, and it has one answer in each direction.</p><p><strong>Their store, read by this server: converted, not shared.</strong> The index that says which message lives at which offset is ours (<code>yarilo.<wbr>map.<wbr>index</code>, <code>yarilo.<wbr>index*</code>), and theirs is in their own format. An mdbox or sdbox store of theirs is therefore <strong>adopted</strong>: on the first open of a folder this server reads their index, writes ours beside it, and removes theirs, leaving the messages exactly where they lie. That is one-way for the whole store from the first open, and it is described in <a href="/latest/installation/migration.html#adoption-this-server-takes-over-the-store-in-place">Migration</a>. Adoption is not sharing: the two servers do not read one store at the same time, and the other one cannot serve it afterwards.</p><p><strong>A folder&#39;s identity outlives its index.</strong> <code>yarilo.<wbr>folders</code>, under the control root, records the UIDVALIDITY each folder was created with. It lives with the mail rather than with the indexes on purpose: removing index files is the operator gesture for forcing a rebuild, and this must survive it. A folder whose index is lost is reopened with the UIDVALIDITY it always had, so clients do not resynchronise. <code>DELETE</code> forgets the entry — RFC 3501 §6.3.4 requires a folder created again under the same name to look new — and <code>RENAME</code> moves it. The file is append-only and folds when it grows past a bound. It can never stop a mailbox opening: unreadable, garbled or unwritable, the folder opens with the value it would have had without it.</p><p>Fresh values come from <code>yarilo-uidvalidity</code> beside it, a counter that only rises and is claimed with a zero-length <code>O_<wbr>EXCL</code> marker, so a number is never issued twice — not to two folders created in one second, and not after a clock steps backwards. The two compose: the allocator guarantees no repeat, the record preserves what was issued.</p><p><strong>An mdbox folder whose index is lost is refused, not served empty.</strong> mdbox folders hold no message files — the mail is in the shared storage and the folder directory carries only indexes — so the filesystem cannot tell a folder that lost its index from one just created. The identity record can, and for a folder it knows the open fails, naming the folder and the recovery, instead of answering <code>0 EXISTS</code> over mail that is still there. For a folder created before the record existed there is no entry and the ambiguity remains: it opens as new.</p><p>Recovery for mdbox is the operator storage-wide rebuild, run with that user&#39;s mailboxes stopped: it recomputes every map record&#39;s refcount, and under live delivery a message saved but not yet appended to its folder would be counted as referenced by nobody and reclaimed by the next purge. A per-folder rebuild is not the answer — the only thing outside the index tying a message to a folder is the storage trailer, which names the folder a message was <em>first</em> saved to, so it would file moved mail back to the wrong place.</p><p>sdbox has no such ambiguity — its messages are files in the folder — and a folder whose index is lost there is rebuilt from them on the next open.</p><p><strong>A yarilo tree, read by them: not possible.</strong> Our index files are ours, nothing converts them back, and pointing another implementation at this tree shows an empty mailbox even though every message file in it would parse.</p><p>Three parity knobs tune when a new <code>m.<wbr>&lt;N&gt;</code> is rolled and how it is allocated (all under <code>storage:</code>, mdbox only):</p><h4 id="storage.mdbox_rotate_size" tabindex="-1"><code>mdbox_<wbr>rotate_<wbr>size</code> <a class="header-anchor" href="#storage.mdbox_rotate_size" aria-label="Permalink to &quot;`mdbox_rotate_size` {#storage.mdbox_rotate_size}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>10M</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>storage.mdbox_rotate_size</code></dd></dl></div><p>Maximum size of an <code>m.<wbr>&lt;N&gt;</code> before the next save rolls to a fresh file: a size (<code>&quot;10M&quot;</code>, <code>&quot;1G&quot;</code>) or a byte count. <code>0</code> or an empty value is refused at startup.</p><h4 id="storage.mdbox_rotate_interval" tabindex="-1"><code>mdbox_<wbr>rotate_<wbr>interval</code> <a class="header-anchor" href="#storage.mdbox_rotate_interval" aria-label="Permalink to &quot;`mdbox_rotate_interval` {#storage.mdbox_rotate_interval}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>storage.mdbox_rotate_interval</code></dd></dl></div><p>Roll the append file once it is older than this, regardless of size: a duration (<code>&quot;30s&quot;</code>, <code>&quot;5m&quot;</code>, <code>&quot;1h&quot;</code>) or a second count. Empty or <code>0</code> never rolls on age.</p><h4 id="storage.mdbox_preallocate_space" tabindex="-1"><code>mdbox_<wbr>preallocate_<wbr>space</code> <a class="header-anchor" href="#storage.mdbox_preallocate_space" aria-label="Permalink to &quot;`mdbox_preallocate_space` {#storage.mdbox_preallocate_space}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>storage.mdbox_preallocate_space</code></dd></dl></div><p><code>fallocate()</code> the new file to <code>mdbox_<wbr>rotate_<wbr>size</code> up front (Linux only; a no-op elsewhere).</p><h4 id="storage.mdbox_map_format" tabindex="-1"><code>mdbox_<wbr>map_<wbr>format</code> <a class="header-anchor" href="#storage.mdbox_map_format" aria-label="Permalink to &quot;`mdbox_map_format` {#storage.mdbox_map_format}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>v2</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>v2</code> <code>v1</code></dd><dt>Helm</dt><dd><code>storage.mdbox_map_format</code></dd></dl></div><p>On-disk format of the per-user map index; see <a href="#mdbox-map-index-format">mdbox map index format</a>.</p><p>The age check reads a <strong>persisted per-file create-time</strong> stored in the map header (not a filesystem <code>btime</code>, which is unreliable over NFS), so it survives restarts. Unlike the reference it uses a <strong>rolling window</strong> (<code>now − createTime &gt; interval</code>) rather than a clock-boundary snap, so &quot;rotate every interval&quot; means the file actually lived at least that long. Preallocation uses <code>FALLOC_<wbr>FL_<wbr>KEEP_<wbr>SIZE</code> so the file&#39;s logical size still grows from zero as records are appended — reserving blocks without breaking the offset model — and any failure is a non-fatal hint.</p><p>The <strong>reactive heal</strong> is retry-bounded per folder per session on the IMAP path: a near-continuous purge/altmove keeps every scan incomplete (the heal aborts rather than mistake a compacted message for a vanished one), so after a few consecutive aborts the session stops auto-retrying that folder — each attempt costs a full storage scan — and logs once, pointing the operator at a rebuild. The counter resets on a successful heal or when another session clears the marker. The <strong>POP3</strong> path carries no such bound: a POP3 session heals at most once, at login, not in a command loop, so it cannot spin; a rapidly reconnecting client during a purge could still reproduce the storm across logins, but POP3 sessions are short and a cross-login bound would need persistent state — an accepted gap.</p><h2 id="mdbox-map-index-format" tabindex="-1">mdbox map index format <a class="header-anchor" href="#mdbox-map-index-format" aria-label="Permalink to &quot;mdbox map index format&quot;">​</a></h2><p>The per-user map index (<code>yarilo.<wbr>map.<wbr>index</code>) is what makes an mdbox COPY O(1): every folder record points at a <code>map_<wbr>uid</code>, and the map resolves that to <code>(file_<wbr>id, offset, size)</code> plus a reference count. Two on-disk formats exist, selected by <code>storage.<wbr>mdbox_<wbr>map_<wbr>format</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Layout</th></tr></thead><tbody><tr><td style="text-align:left;"><code>v2</code> (default)</td><td style="text-align:left;">A fixed 80-byte header and 36-byte records sorted by <code>map_<wbr>uid</code>. A record is addressed by offset arithmetic and found by binary search over the file bytes, so opening the map parses nothing and builds no lookup table. The header also records which append log the base already folded in, and how far.</td></tr><tr><td style="text-align:left;"><code>v1</code></td><td style="text-align:left;">The older mail-index-backed format: a record stream with per-record extensions that has to be parsed into objects before anything can be looked up.</td></tr></tbody></table><p><strong>Changing the value converts the map on the next open, in either direction</strong>, preserving every <code>map_<wbr>uid</code>. Both writers are atomic (temp file + rename), so an interrupted conversion leaves the previous format readable and the next open converts again. A base carrying a version this binary does not know is refused rather than guessed at — the map decides which bytes belong to which message and which file a purge may unlink.</p><p>Choose <code>v1</code> only to keep the map readable by an older yarilo image; it is the reason the setting exists. It gives up what its header cannot hold: with no log lineage and no record digest, a v1 map re-reads its base whenever the file moves and replays its log from the start, and the window between writing the base and dropping the log is unprotected, so a reference-count delta in it can be applied twice.</p><h2 id="durability-what-a-save-promises" tabindex="-1">Durability: what a save promises <a class="header-anchor" href="#durability-what-a-save-promises" aria-label="Permalink to &quot;Durability: what a save promises&quot;">​</a></h2><p><code>storage.<wbr>mail_<wbr>fsync</code> says what has reached the disk by the time a delivery is answered — the LMTP <code>250</code> for a recipient, the <code>OK [APPENDUID]</code> of an APPEND. It takes the same three values as the reference implementation, and the same default.</p><table tabindex="0"><thead><tr><th style="text-align:left;">mode</th><th style="text-align:left;">synced before the answer</th><th style="text-align:left;">what it still does not promise</th></tr></thead><tbody><tr><td style="text-align:left;"><code>never</code></td><td style="text-align:left;">nothing, including the uidlist row</td><td style="text-align:left;">every byte written is in the page cache only</td></tr><tr><td style="text-align:left;"><code>optimized</code> <em>(default)</em></td><td style="text-align:left;">the message body; the uidlist row, as before</td><td style="text-align:left;">the index and its journal, the directory entry</td></tr><tr><td style="text-align:left;"><code>always</code></td><td style="text-align:left;">the above, plus the index journal and the directory after a rename or create</td><td style="text-align:left;">that the directory survives — a synced entry is not a repaired directory</td></tr></tbody></table><p>The body is the half that cannot be rebuilt, which is why <code>optimized</code> syncs it and nothing else: the index, the list and the flags in a name are all reconstructible from the bodies that are on disk. In <code>never</code> even the uidlist row is left to the filesystem, so a crash can hand a file that already had a uid a second one; it is the mode for a stand, or for storage that acknowledges its own writes.</p><p>Where the sync happens matters as much as whether:</p><ul><li><strong>maildir</strong> syncs the file in <code>tmp/</code> <em>before</em> it is named and moved into <code>cur/</code>, so the durable bytes precede the answer rather than follow it.</li><li><strong>mdbox</strong> syncs <code>m.<wbr>&lt;N&gt;</code> <em>before</em> the map records the message, so the map never points at bytes a crash did not write.</li><li>the <strong>index journal</strong> is synced in <code>always</code> only.</li></ul><p>The cost is one <code>fsync</code> per delivered message. In the code it is paid outside any lock — the file is still in <code>tmp/</code>, where no other session can see it — but on a journalling filesystem it is not free of the others: every <code>fsync</code> forces a filesystem-journal commit, the commits serialise, and the uidlist row&#39;s own <code>fsync</code>, which <em>is</em> taken under the folder&#39;s lock, waits behind the commits the other deliveries on that node just caused.</p><p>Measured on ext4 (<code>data=ordered</code>), fifty sessions over twenty accounts, one build with only this key changed:</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:right;"><code>optimized</code></th><th style="text-align:right;"><code>never</code></th></tr></thead><tbody><tr><td style="text-align:left;"><code>fsync</code> calls in a 90-second run</td><td style="text-align:right;">728</td><td style="text-align:right;">0</td></tr><tr><td style="text-align:left;">one <code>fsync</code> of the message body</td><td style="text-align:right;">1.7 ms</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:left;">one <code>fsync</code> of the uidlist row</td><td style="text-align:right;">1.4 ms</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:left;">uidlist lock held, mean</td><td style="text-align:right;"><strong>26 ms</strong></td><td style="text-align:right;"><strong>8.7 ms</strong></td></tr><tr><td style="text-align:left;">index write cycle held, mean</td><td style="text-align:right;">40 ms</td><td style="text-align:right;">29 ms</td></tr></tbody></table><p>So the hold grows with how many deliveries a node is making at once, not with the cost of the call itself. Expect that where a folder is busy, and read <code>maildir_<wbr>lock_<wbr>hold_<wbr>seconds</code> rather than guessing.</p><p><code>never</code> removes both syncs and is for a stand, or for storage that acknowledges a write of its own — a battery-backed controller, or a volume whose mount makes the guarantee. A deployment can also get a stronger guarantee than <code>always</code> from the mount (<code>sync</code>, or a filesystem whose journal covers data); <code>mail_<wbr>fsync</code> is what yarilo itself promises.</p><p>Index writes are a separate matter: the base is replaced atomically (temp file</p><ul><li>rename) and the log is append-only, so a crash costs the tail of the log rather than the folder. The <code>mail_<wbr>volatile_<wbr>path</code> setting moves the index&#39;s temporary file — and its fsync — off the mail volume, which is why it is worth setting on NFS deployments (see <a href="#path-templates">Path templates</a>).</li></ul><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mail_fsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">optimized</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # never | optimized | always</span></span></code></pre></div><p>The Helm chart exposes it under <code>storage</code> by the same name.</p><h2 id="when-a-log-folds-and-what-it-costs-not-to" tabindex="-1">When a log folds, and what it costs not to <a class="header-anchor" href="#when-a-log-folds-and-what-it-costs-not-to" aria-label="Permalink to &quot;When a log folds, and what it costs not to&quot;">​</a></h2><p>Every append to a folder&#39;s index goes to a log beside it; the log is folded into the base file when it gets big enough or old enough. Three settings decide when, and each works on its own — set one and the other two keep their built-in values.</p><h3 id="storage.mail_index_log_rotate_min_size" tabindex="-1"><code>mail_<wbr>index_<wbr>log_<wbr>rotate_<wbr>min_<wbr>size</code> <a class="header-anchor" href="#storage.mail_index_log_rotate_min_size" aria-label="Permalink to &quot;`mail_index_log_rotate_min_size` {#storage.mail_index_log_rotate_min_size}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>32k</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>storage.mail_index_log_rotate_min_size</code></dd></dl></div><p>Below this size a log is never folded.</p><h3 id="storage.mail_index_log_rotate_min_age" tabindex="-1"><code>mail_<wbr>index_<wbr>log_<wbr>rotate_<wbr>min_<wbr>age</code> <a class="header-anchor" href="#storage.mail_index_log_rotate_min_age" aria-label="Permalink to &quot;`mail_index_log_rotate_min_age` {#storage.mail_index_log_rotate_min_age}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>60</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>storage.mail_index_log_rotate_min_age</code></dd></dl></div><p>Above the floor, fold once the log is this old.</p><h3 id="storage.mail_index_log_rotate_max_size" tabindex="-1"><code>mail_<wbr>index_<wbr>log_<wbr>rotate_<wbr>max_<wbr>size</code> <a class="header-anchor" href="#storage.mail_index_log_rotate_max_size" aria-label="Permalink to &quot;`mail_index_log_rotate_max_size` {#storage.mail_index_log_rotate_max_size}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>1M</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>storage.mail_index_log_rotate_max_size</code></dd></dl></div><p>Fold regardless of age.</p><p>The same three govern the mdbox map log, which grows more slowly and therefore folds less often. One policy, different rates.</p><h3 id="why-the-floor-exists" tabindex="-1">Why the floor exists <a class="header-anchor" href="#why-the-floor-exists" aria-label="Permalink to &quot;Why the floor exists&quot;">​</a></h3><p><strong>Every open replays the log tail.</strong> Measured on an account with a real mailbox: a folder whose log has just been folded opens in ~7.5 ms, one carrying 27 KB of log opens in ~17 ms — roughly <strong>0.4 ms per kilobyte of log</strong>. The floor is what bounds that: it is the cost of opening a mailbox that sits between folds, not a tuning knob for how often folding happens.</p><h3 id="why-the-age-gate-exists-and-why-it-is-60-s" tabindex="-1">Why the age gate exists, and why it is 60 s <a class="header-anchor" href="#why-the-age-gate-exists-and-why-it-is-60-s" aria-label="Permalink to &quot;Why the age gate exists, and why it is 60 s&quot;">​</a></h3><p>The age gate stops a fold firing inside a burst of appends — a log that is still growing is not worth folding, since it will cross the floor again in a moment. It only has to outlast a typical delivery burst.</p><p>At the 5 min it used to be, an actively delivering account carried its log to ~110 KB past the floor, and across that interval delivery p50 went 74 → 103 ms while <strong>p99 went 127 → 249 ms</strong>. At 60 s the log folds about once per hundred deliveries and p99 stays at ~128 ms.</p><h3 id="what-the-floor-does-not-do" tabindex="-1">What the floor does not do <a class="header-anchor" href="#what-the-floor-does-not-do" aria-label="Permalink to &quot;What the floor does not do&quot;">​</a></h3><p>The floor only matters when a log grows <strong>slower</strong> than the floor between folds — and on an account taking deliveries, it does not.</p><p>A fold does not empty the log: it leaves the recent records behind, measured at 10–18 KB. A hundred deliveries then add roughly 18 KB more, so the log stands at 28–36 KB by the end of each window — far past a 16 KiB floor every time, and around a 32 KiB one, above it in some windows and just short in others. Either way the size condition is met while the log is already older than the 60 s gate, so what paces the cycle is the <strong>age</strong>, not the floor.</p><p>Nine measured windows at 32 KiB and 16 KiB were indistinguishable: medians 76.0 and 71.8 ms with overlapping ranges, one fold per window in both.</p><p>So on a busy account the tail is held by the <strong>age gate</strong>, not by the floor. Lowering the floor there buys nothing. Raising it is what an operator with a <strong>large, quietly-delivering</strong> mailbox might do — there the log grows slower than the floor, folds are the rarer cost, and a higher floor means fewer of them.</p><p>Delivery p50 still moves within a fold cycle — roughly 55–95 ms on the measured account, cheapest just after a fold. That range is the price of a cheap open: lowering the floor to flatten it would lengthen every open instead, at the rate above.</p><h2 id="folding-indexes-before-a-measurement" tabindex="-1">Folding indexes before a measurement <a class="header-anchor" href="#folding-indexes-before-a-measurement" aria-label="Permalink to &quot;Folding indexes before a measurement&quot;">​</a></h2><p><code>yarctl backend index optimize &lt;user&gt; --all</code> folds every folder index of the account <strong>and</strong>, for mdbox, the per-user map. Both are structures a session replays when it opens; folding them is what makes an open cost what it will cost in steady state.</p><p>This matters for benchmarking specifically, and the reason is worth stating because it is not obvious: <strong>a read-only workload never folds anything.</strong> The map log is folded by writes, and a FETCH-only profile performs none — so a freshly seeded account replays the entire seed on every session open, in every window, and discarding the first run does not help because the state is not warming up, it is stationary. One measured account showed 36.8 ms per map open against 0.23 ms after a fold.</p><p>So the sequence for any comparative run is:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># seed the account, then</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimize</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># and only then start the measurement window</span></span></code></pre></div><p>Do not use <code>rebuild</code> for this. A rebuild scans storage and reconciles state; a fold writes the base and drops the log. They are different operations, and the expensive one standing in for the cheap one is how a seeding script ends up doing eleven full storage scans to get the effect of eleven folds.</p><h2 id="file-locks-the-index-cache-and-write-concurrency" tabindex="-1">File locks, the index cache and write concurrency <a class="header-anchor" href="#file-locks-the-index-cache-and-write-concurrency" aria-label="Permalink to &quot;File locks, the index cache and write concurrency&quot;">​</a></h2><p>All under <code>storage:</code>.</p><h3 id="storage.storage_lock_method" tabindex="-1"><code>storage_<wbr>lock_<wbr>method</code> <a class="header-anchor" href="#storage.storage_lock_method" aria-label="Permalink to &quot;`storage_lock_method` {#storage.storage_lock_method}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>flock</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>flock</code> <code>fcntl</code> <code>dotlock</code></dd><dt>Helm</dt><dd><code>storage.storage_lock_method</code></dd></dl></div><p>How a write to a shared file — an index, a uidlist — excludes another writer. Pick what the mail volume supports; a dict of the <code>file</code> driver should use the same.</p><h3 id="storage.storage_lock_stale_timeout" tabindex="-1"><code>storage_<wbr>lock_<wbr>stale_<wbr>timeout</code> <a class="header-anchor" href="#storage.storage_lock_stale_timeout" aria-label="Permalink to &quot;`storage_lock_stale_timeout` {#storage.storage_lock_stale_timeout}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>180</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>storage.storage_lock_stale_timeout</code></dd></dl></div><p>How long a dotlock may sit unchanged before a waiter takes it over; <code>0</code> never takes one over. Only <code>dotlock</code> has the question: <code>flock</code> and <code>fcntl</code> locks die with the process that held them.</p><h3 id="storage.mail_cache_purge_delete_percentage" tabindex="-1"><code>mail_<wbr>cache_<wbr>purge_<wbr>delete_<wbr>percentage</code> <a class="header-anchor" href="#storage.mail_cache_purge_delete_percentage" aria-label="Permalink to &quot;`mail_cache_purge_delete_percentage` {#storage.mail_cache_purge_delete_percentage}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>20</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>storage.mail_cache_purge_delete_percentage</code></dd></dl></div><p>Purge a folder&#39;s cache file once this share of its records belongs to messages that are gone; <code>0</code> never purges on that ground.</p><h3 id="storage.mail_cache_purge_continued_percentage" tabindex="-1"><code>mail_<wbr>cache_<wbr>purge_<wbr>continued_<wbr>percentage</code> <a class="header-anchor" href="#storage.mail_cache_purge_continued_percentage" aria-label="Permalink to &quot;`mail_cache_purge_continued_percentage` {#storage.mail_cache_purge_continued_percentage}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>200</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>storage.mail_cache_purge_continued_percentage</code></dd></dl></div><p>Purge it once its continued records reach this percentage of the live ones; <code>0</code> never purges on that ground.</p><h3 id="storage.mail_cache_purge_min_size" tabindex="-1"><code>mail_<wbr>cache_<wbr>purge_<wbr>min_<wbr>size</code> <a class="header-anchor" href="#storage.mail_cache_purge_min_size" aria-label="Permalink to &quot;`mail_cache_purge_min_size` {#storage.mail_cache_purge_min_size}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>32k</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>storage.mail_cache_purge_min_size</code></dd></dl></div><p>Below this size the cache file is never purged; <code>&quot;0&quot;</code> allows a purge at any size.</p><h3 id="storage.max_concurrent_writes" tabindex="-1"><code>max_<wbr>concurrent_<wbr>writes</code> <a class="header-anchor" href="#storage.max_concurrent_writes" aria-label="Permalink to &quot;`max_concurrent_writes` {#storage.max_concurrent_writes}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>0</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>storage.max_concurrent_writes</code></dd></dl></div><p>Cap on message bodies being written to disk at once, per process, for every driver; <code>0</code> is unlimited. A slow volume can be kept from being swamped by a burst; spinning disks suit a few dozen, SSDs a few hundred.</p><h2 id="folder-names-on-disk" tabindex="-1">Folder names on disk <a class="header-anchor" href="#folder-names-on-disk" aria-label="Permalink to &quot;Folder names on disk&quot;">​</a></h2><p>A client chooses folder names, and the storage layout turns them into paths. These settings decide which names are refused, and how the rest are written. All under <code>storage:</code>.</p><h3 id="storage.mailbox_list_validate_fs_names" tabindex="-1"><code>mailbox_<wbr>list_<wbr>validate_<wbr>fs_<wbr>names</code> <a class="header-anchor" href="#storage.mailbox_list_validate_fs_names" aria-label="Permalink to &quot;`mailbox_list_validate_fs_names` {#storage.mailbox_list_validate_fs_names}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>storage.mailbox_list_validate_fs_names</code></dd></dl></div><p>Refuse names that are unsafe as paths: <code>.</code> and <code>.<wbr>.</code> segments, adjacent separators, a leading <code>/</code> or <code>~</code>, and the on-disk separator when the namespace speaks another one. Turn it off only for a driver that never builds a path from the name.</p><h3 id="storage.mailbox_list_reserved_segments" tabindex="-1"><code>mailbox_<wbr>list_<wbr>reserved_<wbr>segments</code> <a class="header-anchor" href="#storage.mailbox_list_reserved_segments" aria-label="Permalink to &quot;`mailbox_list_reserved_segments` {#storage.mailbox_list_reserved_segments}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>cur, new, tmp, dbox-Mails, fts-flatcurve</code></dd><dt>Type</dt><dd>list</dd><dt>Helm</dt><dd><code>storage.mailbox_list_reserved_segments</code></dd></dl></div><p>Names a single hierarchy segment may not take, because the layout owns that directory. Only the names the layout in use actually owns are enforced (see the table below). Empty disables the check. It is retroactive: a user who already has such a folder loses access to it.</p><h3 id="storage.mailbox_list_refuse_layout_separator" tabindex="-1"><code>mailbox_<wbr>list_<wbr>refuse_<wbr>layout_<wbr>separator</code> <a class="header-anchor" href="#storage.mailbox_list_refuse_layout_separator" aria-label="Permalink to &quot;`mailbox_list_refuse_layout_separator` {#storage.mailbox_list_refuse_layout_separator}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>storage.mailbox_list_refuse_layout_separator</code></dd></dl></div><p>Refuse a name containing the on-disk separator when the namespace speaks a different one — with namespace <code>/</code> over Maildir++, <code>a.<wbr>b</code> and <code>a/<wbr>b</code> both land on <code>.<wbr>a.<wbr>b</code>. Retroactive against ordinary names such as <code>example.<wbr>com</code>, so check that no mailbox holds one before turning it on.</p><h3 id="storage.mailbox_list_storage_escape_char" tabindex="-1"><code>mailbox_<wbr>list_<wbr>storage_<wbr>escape_<wbr>char</code> <a class="header-anchor" href="#storage.mailbox_list_storage_escape_char" aria-label="Permalink to &quot;`mailbox_list_storage_escape_char` {#storage.mailbox_list_storage_escape_char}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>storage.mailbox_list_storage_escape_char</code></dd></dl></div><p>Store such names escaped instead of refusing them; see below. Not retroactive.</p><h3 id="storage.mailbox_list_normalize_names_to_nfc" tabindex="-1"><code>mailbox_<wbr>list_<wbr>normalize_<wbr>names_<wbr>to_<wbr>nfc</code> <a class="header-anchor" href="#storage.mailbox_list_normalize_names_to_nfc" aria-label="Permalink to &quot;`mailbox_list_normalize_names_to_nfc` {#storage.mailbox_list_normalize_names_to_nfc}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Also accepted as</dt><dd><code>mailbox_list_normalize_to_nfc</code></dd><dt>Helm</dt><dd><code>storage.mailbox_list_normalize_names_to_nfc</code></dd></dl></div><p>Normalise names to Unicode NFC before they are stored or compared, so differently composed spellings of one name are one folder.</p><h3 id="storage.mailbox_list_utf8" tabindex="-1"><code>mailbox_<wbr>list_<wbr>utf8</code> <a class="header-anchor" href="#storage.mailbox_list_utf8" aria-label="Permalink to &quot;`mailbox_list_utf8` {#storage.mailbox_list_utf8}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>storage.mailbox_list_utf8</code></dd></dl></div><p>Write names as UTF-8 on disk; <code>false</code> writes modified UTF-7, for a store that already uses it.</p><h2 id="moving-a-user-between-mailbox-formats" tabindex="-1">Moving a user between mailbox formats <a class="header-anchor" href="#moving-a-user-between-mailbox-formats" aria-label="Permalink to &quot;Moving a user between mailbox formats&quot;">​</a></h2><p>One folder name is legal under one format and not under another: <strong><code>dbox-Mails</code></strong>. Maildir++ gives every folder a leading <code>.</code>, so <code>.<wbr>dbox-Mails</code> collides with nothing; the dbox layouts store a folder as <code>mailboxes/<wbr>&lt;name&gt;/<wbr>dbox-Mails</code>, where that name is their own marker, and a folder called <code>dbox-Mails</code> would produce <code>mailboxes/<wbr>dbox-Mails/<wbr>dbox-Mails</code> — an outer directory that is a folder and an inner one that is a marker, indistinguishable to a tree walk. So it is refused on mdbox and sdbox and accepted on maildir:</p><table tabindex="0"><thead><tr><th style="text-align:left;">name</th><th style="text-align:left;">mdbox</th><th style="text-align:left;">maildir</th><th style="text-align:left;">sdbox</th></tr></thead><tbody><tr><td style="text-align:left;"><code>New</code>, <code>cur</code>, <code>new</code>, <code>tmp</code></td><td style="text-align:left;">OK</td><td style="text-align:left;">OK</td><td style="text-align:left;">OK</td></tr><tr><td style="text-align:left;"><code>dbox-Mails</code></td><td style="text-align:left;"><code>NO [CANNOT]</code></td><td style="text-align:left;"><strong>OK</strong></td><td style="text-align:left;"><code>NO [CANNOT]</code></td></tr><tr><td style="text-align:left;"><code>fts-flatcurve</code></td><td style="text-align:left;"><code>NO [CANNOT]</code></td><td style="text-align:left;"><strong>OK</strong></td><td style="text-align:left;"><code>NO [CANNOT]</code></td></tr></tbody></table><p>The first row is the reserved-segment rule working as intended: only the names the layout in use actually owns are enforced, and no layout owns those.</p><p><code>fts-flatcurve</code> is the full-text index directory a store converted from the reference keeps inside a dbox mailbox directory. It is never listed as a folder, and on mdbox and sdbox no folder of that name can be created.</p><p><strong>It is a precondition, not a wall.</strong> Set <code>mailbox_<wbr>list_<wbr>storage_<wbr>escape_<wbr>char</code> on the target and the name is stored escaped, out from under the marker:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>esc=&quot;&quot;   ValidateName(&quot;dbox-Mails&quot;) = refused</span></span>\n<span class="line"><span>         path = mailboxes/dbox-Mails/dbox-Mails        &lt;- the collision</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>esc=&quot;^&quot;  ValidateName(&quot;dbox-Mails&quot;) = accepted</span></span>\n<span class="line"><span>         path = mailboxes/^64box-Mails/dbox-Mails      &lt;- stored literally</span></span></code></pre></div><p>Escaping supersedes the refusals that exist because a name could not be <em>represented</em>, which is what this one is. So the rule for a format migration is:</p><ul><li><strong>without an escape character on the target</strong> — such a folder cannot be migrated;</li><li><strong>with one configured</strong> — it migrates and is stored escaped.</li></ul><p>And it inherits that key&#39;s retroactivity: enabling it is <strong>not</strong> retroactive, so it has to be set on the target <strong>before</strong> the mail arrives, not after.</p><p>This is the only name that exists under one driver and cannot exist under another, which is why it is stated here rather than left to be discovered.</p>',156)])])}const p=t(d,[["render",r]]);export{g as __pageData,p as default};
